if(key==="nexus-logistics")return '<div class="infographic inf-logistics"><span>ПРИЁМ</span><b>→</b><span>ХРАНЕНИЕ</span><b>→</b><span>КОМПЛЕКТАЦИЯ</span><b>→</b><span>ОТГРУЗКА</span></div>';
