function bindConcierge(faq){
const box=document.querySelector(".concierge"),toggle=document.querySelector(".concierge-toggle"),close=document.querySelector(".concierge-close");
if(!box||!toggle)return;
toggle.onclick=()=>box.classList.toggle("is-open");
close.onclick=()=>box.classList.remove("is-open");
document.querySelectorAll(".concierge-questions button").forEach(btn=>btn.onclick=()=>{
const item=faq[Number(btn.dataset.answer)];
box.querySelector(".concierge-answer").textContent=item[1];
});
}
function renderEconomy(p){
const fields=p.eco.fields.map((f,i)=>'<label>'+esc(f[0])+'<input data-key="'+esc(f[1])+'" data-i="'+i+'" type="number" min="0" step="any" inputmode="decimal" placeholder="Введите значение"></label>').join("");
return '<div class="eco-layout"><div class="eco-inputs">'+fields+'</div><div id="results" class="results"><div class="result-empty"><b>Готово к расчёту.</b><span>Введите все исходные данные. Значения не подставляются автоматически.</span></div></div></div>';
}
function calc(kind,v){
const n=k=>Number(v[k]||0); let rows=[];
if(kind==="aladin"){
const revenue=n("units")*n("area")*n("price"), costs=n("units")*n("area")*n("build")+n("land")+n("design")+n("utilities")+n("sales")+n("reserve"), profit=revenue-costs;
if(n("investor")+n("mmw")>100)return {error:"Доли инвестора и MMW не могут суммарно превышать 100%."};
rows=[["Выручка от продаж",revenue],["Совокупные затраты",costs],["Результат проекта",profit],["Результат на дом",n("units")?profit/n("units"):0],["ROI",costs?profit/costs*100:0,"percent"],["Безубыточная цена / м²",n("units")&&n("area")?costs/(n("units")*n("area")):0],["Доход инвестора",profit*n("investor")/100],["Доход MMW",profit*n("mmw")/100]];
}
if(kind==="space"){
const occupied=n("area")*n("occupancy")/100, rent=occupied*n("rate"), gross=rent+n("extra"), operating=gross-n("opex"), annual=operating*12;
rows=[["Доход от площадей / месяц",rent],["Дополнительная выручка / месяц",n("extra")],["Операционный результат / месяц",operating],["Операционный результат / год",annual],["ROI / год",n("capex")?annual/n("capex")*100:0,"percent"],["Точка безубыточности по загрузке",n("area")&&n("rate")?Math.max(0,(n("opex")-n("extra"))/(n("area")*n("rate"))*100):0,"percent"],["Окупаемость",operating>0&&n("capex")?n("capex")/operating:0,"months"]];
}
if(kind==="logistics"){
const storage=n("area")*n("occupancy")/100*n("rate"), handling=n("extra"), gross=storage+handling, operating=gross-n("opex"), annual=operating*12;
rows=[["Выручка хранения / месяц",storage],["Выручка обработки и сервиса / месяц",handling],["Общая выручка / месяц",gross],["Операционный результат / месяц",operating],["Результат / год",annual],["ROI / год",n("capex")?annual/n("capex")*100:0,"percent"],["Окупаемость",operating>0&&n("capex")?n("capex")/operating:0,"months"]];
}
if(kind==="hospitality"){
const roomRevenue=n("rooms")*n("occupancy")/100*n("adr")*n("days"), gross=roomRevenue+n("extra"), result=gross-n("opex");
rows=[["Выручка размещения / период",roomRevenue],["Дополнительная выручка / период",n("extra")],["Общая выручка / период",gross],["Операционный результат / период",result],["ROI / период",n("capex")?result/n("capex")*100:0,"percent"],["Окупаемость / периодов",result>0&&n("capex")?n("capex")/result:0,"periods"]];
}
if(kind==="processing"){
const output=n("raw")*n("yield")/100, revenue=output*n("price"), result=revenue-n("opex");
rows=[["Выход готового продукта",output],["Выручка от продукта / месяц",revenue],["Операционный результат / месяц",result],["ROI / месяц",n("capex")?result/n("capex")*100:0,"percent"],["Окупаемость / месяцев",result>0&&n("capex")?n("capex")/result:0,"months"]];
}
if(kind==="energy"){
const hours=n("hours"), available=n("power")*hours, supplied=available*n("occupancy")/100, revenue=supplied*n("rate"), annualRevenue=revenue*12, annualOpex=n("opex")*12, annualResult=annualRevenue-annualOpex;
rows=[["Доступная энергия / месяц, кВт·ч",available],["Реализованная энергия / месяц, кВт·ч",supplied],["Выручка / месяц",revenue],["Операционный результат / год",annualResult],["ROI / год",n("capex")?annualResult/n("capex")*100:0,"percent"],["Окупаемость",annualResult>0&&n("capex")?n("capex")/annualResult*12:0,"months"]];
}
return {rows};
}
function formatValue(value,unit){
if(unit==="percent")return money(value)+" %";
if(unit==="months"||unit==="periods")return money(value)+" "+(unit==="months"?"мес.":"периодов");
return money(value);
}
function bindBlocks(p){
const blocks=[...document.querySelectorAll(".project-block")];
if(!blocks.length)return;
blocks.forEach((block,index)=>{
const trigger=block.querySelector(".block-trigger");
if(!trigger)return;
trigger.addEventListener("click",()=>{
const open=block.classList.contains("is-open");
if(p.mechanic==="accordion"){
blocks.forEach(b=>{b.classList.remove("is-open");b.querySelector(".block-trigger")?.setAttribute("aria-expanded","false")});
if(!open){block.classList.add("is-open");trigger.setAttribute("aria-expanded","true")}
}
else if(p.mechanic==="slide"){
blocks.forEach(b=>{b.classList.remove("is-open");b.querySelector(".block-trigger")?.setAttribute("aria-expanded","false")});
block.classList.add("is-open");trigger.setAttribute("aria-expanded","true");
block.scrollIntoView({behavior:"smooth",block:"nearest"});
}
else if(p.mechanic==="flow"){
if(open){block.classList.remove("is-open");trigger.setAttribute("aria-expanded","false")}
else{
blocks.slice(0,index+1).forEach(b=>{b.classList.add("is-open");b.querySelector(".block-trigger")?.setAttribute("aria-expanded","true")});
}
}
else if(p.mechanic==="fade"){
block.classList.toggle("is-open");trigger.setAttribute("aria-expanded",String(!open));
}
else if(p.mechanic==="stack"){
if(open){block.classList.remove("is-open");trigger.setAttribute("aria-expanded","false")}
else{
blocks.forEach(b=>{b.classList.remove("is-open");b.querySelector(".block-trigger")?.setAttribute("aria-expanded","false")});
block.classList.add("is-open");trigger.setAttribute("aria-expanded","true");
}
}
else if(p.mechanic==="scan"){
blocks.forEach(b=>{if(b!==block){b.classList.remove("is-open");b.querySelector(".block-trigger")?.setAttribute("aria-expanded","false")}});
block.classList.toggle("is-open");trigger.setAttribute("aria-expanded",String(!open));
block.classList.toggle("is-scanning",!open);
setTimeout(()=>block.classList.remove("is-scanning"),700);
}
});
});
}
function bindEconomy(p){
const inputs=[...document.querySelectorAll(".eco-inputs input")];
const run=()=>{
const complete=inputs.every(x=>x.value.trim()!=="");
const out=document.getElementById("results");
if(!complete){out.innerHTML='<div class="result-empty"><b>Расчёт не выполнен.</b><span>Заполните все поля, чтобы получить результат.</span></div>';return}
const v=Object.fromEntries(inputs.map(x=>[x.dataset.key,Number(x.value)]));
const invalid=inputs.find(x=>{const n=Number(x.value),k=x.dataset.key;return !Number.isFinite(n)||n<0||(k==="occupancy"&&n>100)||(k==="yield"&&n>100)||(k==="investor"&&n>100)||(k==="mmw"&&n>100)||(k==="hours"&&n>744)});
if(invalid){out.innerHTML='<div class="result-empty error"><b>Проверьте исходные данные.</b><span>Значения не могут быть отрицательными; проценты — выше 100%.</span></div>';return}
const result=calc(p.eco.kind,v);
if(result.error){out.innerHTML='<div class="result-empty error">'+esc(result.error)+'</div>';return}
out.innerHTML=result.rows.map(r=>'<div class="result"><span>'+esc(r[0])+'</span><b>'+formatValue(r[1],r[2])+'</b></div>').join("")+
'<p class="eco-note">Расчёт показывает взаимосвязь введённых данных и не является гарантией доходности.</p>';
};
inputs.forEach(x=>x.addEventListener("input",run));
}
